<?php
declare(strict_types=1);defined('_JEXEC')or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;?>
<?php if(isset($program['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($program['error']);?></div><?php else:$venue=$program['venue'];?><div><?php if((bool)$params->get('show_venue',1)):?><div class="d-flex gap-3 align-items-start mb-3"><?php if((bool)$params->get('show_image',1)&&$venue->picture):?><img src="<?php echo htmlspecialchars((string)$venue->picture,ENT_QUOTES,'UTF-8');?>" alt="" width="72" height="72" class="img-fluid" loading="lazy"><?php else:?><span class="icon-location fs-2 text-body-secondary" aria-hidden="true"></span><?php endif;?><div><h3 class="h5 mb-1"><a href="<?php echo Route::_('index.php?option=com_joomleague&view=venue&venue_id='.(int)$venue->id);?>"><?php echo htmlspecialchars((string)$venue->name,ENT_QUOTES,'UTF-8');?></a></h3><?php if((bool)$params->get('show_address',1)):?><div class="small text-body-secondary"><?php echo htmlspecialchars(trim((string)$venue->city.(($venue->city&&$venue->country_code)?', ':'').(string)$venue->country_code),ENT_QUOTES,'UTF-8');?></div><?php endif;?></div></div><?php endif;?><?php if($program['items']===[]):?><div class="alert alert-info mb-0"><?php echo Text::_('MOD_JOOMLEAGUE_VENUE_PROGRAM_EMPTY');?></div><?php else:?><div class="list-group"><?php foreach($program['items']as$item):?><a class="list-group-item list-group-item-action" href="<?php echo Route::_('index.php?option=com_joomleague&view=eventreport&event_id='.(int)$item['id']);?>"><div class="d-flex flex-wrap justify-content-between gap-2"><strong><?php echo htmlspecialchars(implode(' · ',array_column($item['participants'],'name')),ENT_QUOTES,'UTF-8');?></strong><time class="small text-body-secondary"><?php echo HTMLHelper::_('date',$item['scheduled_start'],Text::_('DATE_FORMAT_LC2'),'UTC');?></time></div><?php if((bool)$params->get('show_context',1)):?><small class="text-body-secondary"><?php echo htmlspecialchars((string)$item['project_name'],ENT_QUOTES,'UTF-8');?><?php if($item['round_name']):?> <span aria-hidden="true">·</span> <?php echo htmlspecialchars((string)$item['round_name'],ENT_QUOTES,'UTF-8');?><?php endif;?></small><?php endif;?></a><?php endforeach;?></div><?php endif;?></div><?php endif;?>
